use crate::fea::StressGrid; use crate::geom::{self,FillPolyline,LayerSurface,Vec3};
pub fn fill_layers(layers:&[LayerSurface],grid:&StressGrid,spacing:f64)->Vec<FillPolyline>{let spacing=spacing.max(1e-6);let mut out=Vec::new();for layer in layers{if layer.points.len()<2{continue}let feed=mean_inplane_feed(layer,grid);let normal_ref=mean_normal(layer);let binormal=geom::normalize(geom::cross(normal_ref,feed));let origin=layer.points[0];let mut u_vals=Vec::new();let mut v_vals=Vec::new();for p in &layer.points{let d=geom::sub(*p,origin);u_vals.push(geom::dot(d,feed));v_vals.push(geom::dot(d,binormal));}let(u_min,u_max)=min_max(&u_vals);let(v_min,v_max)=min_max(&v_vals);let mut stripe_v=v_min;let mut flip=false;while stripe_v<=v_max+1e-9{let mut pts=Vec::new();let mut tvs=Vec::new();let mut feeds=Vec::new();let mut u=u_min;while u<=u_max+1e-9{let q=geom::add(origin,geom::add(geom::scale(feed,u),geom::scale(binormal,stripe_v)));if let Some((p,n))=nearest_on_layer(layer,q,spacing*1.75){pts.push(p);tvs.push(n);feeds.push(feed)}u+=spacing}if pts.len()>=2{if flip{pts.reverse();tvs.reverse();feeds.reverse()}out.push(FillPolyline{layer_id:layer.id,points:pts,tool_vectors:tvs,feed_directions:feeds});flip=!flip}stripe_v+=spacing}}out}
fn mean_normal(l:&LayerSurface)->Vec3{let mut a=[0.0,0.0,0.0];for n in &l.normals{a=geom::add(a,*n)}geom::normalize(a)}fn mean_inplane_feed(l:&LayerSurface,g:&StressGrid)->Vec3{let n=mean_normal(l);let mut a=[0.0,0.0,0.0];if !g.is_empty(){for p in l.points.iter().step_by(l.points.len().max(1)/8+1){let d=sample_direction(g,*p);a=geom::add(a,geom::sub(d,geom::scale(n,geom::dot(d,n))))}}if geom::norm(a)<1e-9{geom::normalize([1.0,0.0,0.0])}else{geom::normalize(a)}}fn sample_direction(g:&StressGrid,p:Vec3)->Vec3{let mut best=0;let mut bd=f64::INFINITY;for k in 0..g.dims[2]{for j in 0..g.dims[1]{for i in 0..g.dims[0]{let q=g.position(i,j,k);let d=geom::dot(geom::sub(p,q),geom::sub(p,q));if d<bd{bd=d;best=g.index(i,j,k)}}}}g.directions[best]}fn nearest_on_layer(l:&LayerSurface,q:Vec3,r:f64)->Option<(Vec3,Vec3)>{let r2=r*r;let mut bi=None;let mut bd=f64::INFINITY;for(i,p)in l.points.iter().enumerate(){let d=geom::dot(geom::sub(q,*p),geom::sub(q,*p));if d<=r2&&d<bd{bd=d;bi=Some(i)}}bi.map(|i|(l.points[i],geom::normalize(l.normals.get(i).copied().unwrap_or([0.0,0.0,1.0]))))}fn min_max(v:&[f64])->(f64,f64){if v.is_empty(){(0.0,0.0)}else{(v.iter().cloned().fold(f64::INFINITY,f64::min),v.iter().cloned().fold(f64::NEG_INFINITY,f64::max))}}
